/* v585: «حذف» بصفحة التصنيف — يسأل أول، وبعد الحذف يختفي من القائمة فوراً */
async function cpDelOne(pid){
  if(!(await delProduct(pid))) return;
  try{ if(myShopDoc && Array.isArray(myShopDoc.products)) myShopDoc.products=myShopDoc.products.filter(x=>_cpPid(x)!==pid) }catch(e){}
  _cpLinks=_cpLinks.filter(x=>x!==pid);
  cpPaintList();
}

/* v583: شعار البراند — يتحفظ مثل ما هو (بلا قص ولا شيل خلفية)، على أرضية بيضاء */
function brImgPick(id){
  let f=document.getElementById('brImgFile');
  if(!f){ f=document.createElement('input'); f.type='file'; f.accept='image/*'; f.id='brImgFile'; f.style.display='none'; f.onchange=()=>brImgUp(f); document.body.appendChild(f) }
  window._brImgId=id; f.value=''; f.click();
}
function _logoBlob(file){
  return new Promise((res,rej)=>{
    const u=URL.createObjectURL(file), im=new Image();
    im.onerror=()=>{ URL.revokeObjectURL(u); rej(new Error('صورة غير صالحة')) };
    im.onload=()=>{
      const S=400, pad=24, r=Math.min((S-pad*2)/im.width,(S-pad*2)/im.height), w=Math.round(im.width*r), h=Math.round(im.height*r);
      const c=document.createElement('canvas'); c.width=S; c.height=S; const x=c.getContext('2d');
      x.fillStyle='#fff'; x.fillRect(0,0,S,S); x.drawImage(im,(S-w)/2,(S-h)/2,w,h); URL.revokeObjectURL(u);
      c.toBlob(b=>b?res(b):rej(new Error('فشل الضغط')),'image/jpeg',0.9);
    };
    im.src=u;
  });
}
async function brImgUp(inp){
  const file=inp.files&&inp.files[0], id=window._brImgId; inp.value=''; if(!file||!id) return;
  try{
    toast('… جاري رفع الشعار');
    const url=await _upBlob(await _logoBlob(file),'brands');
    await rpc('shop_brand_set_img',{p_id:id, p_img:url});
    const b=(_brMine||[]).find(x=>x.id===id); if(b) b.img=url;
    renderMyBrands(); toast('انحفظ الشعار ✓');
  }catch(e){ toast('ما انحفظ: '+errMsg(e)) }
}

