const ni=ps.filter(p=>{ if(!p.img) return true; const z=pSizes(p); return z.some(x=>x.img) && z.some(x=>!x.img) });
if(ni.length) G.unshift({k:'__noimg', n:'بدون صورة', L:ni, ni:true});
